const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

const STORAGE_KEY = 'todos-vanillajs';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function qs(doc, sel) {
  return doc.querySelector(sel);
}

function qsa(doc, sel) {
  return Array.from(doc.querySelectorAll(sel));
}

function todoLabel(doc, text) {
  const items = qsa(doc, '.todo-list li');
  return items.find(function (li) {
    return li.querySelector('label') && li.querySelector('label').textContent.trim() === text;
  });
}

function todoIndex(doc, text) {
  const items = qsa(doc, '.todo-list li');
  for (var i = 0; i < items.length; i++) {
    if (items[i].querySelector('label') && items[i].querySelector('label').textContent.trim() === text) {
      return i;
    }
  }
  return -1;
}

function setInputValue(input, value) {
  input.value = value;
  var evt = input.ownerDocument.createEvent('HTMLEvents');
  evt.initEvent('input', true, true);
  input.dispatchEvent(evt);
}

function triggerEvent(el, type) {
  var evt = el.ownerDocument.createEvent('HTMLEvents');
  evt.initEvent(type, true, true);
  el.dispatchEvent(evt);
}

function triggerKeyboardEvent(el, type, key) {
  var evt = el.ownerDocument.createEvent('KeyboardEvent');
  evt.initKeyboardEvent(type, true, true, null, 0, false, false, false, false, key);
  el.dispatchEvent(evt);
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // The world.js Before hook already calls loadApp(), so the app is ready.
  // Just confirm the document is present.
  assert.ok(this.document, 'App document should be loaded');
});

Given('there are no todos', function () {
  // The app starts with no todos; clear localStorage if needed.
  this.localStorage.removeItem(STORAGE_KEY);
  // Reload the app to get a clean state
  this.loadApp();
});

Given('I have a todo {string}', function (title) {
  this.localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: Date.now(), title: title, completed: false }
  ]));
  this.loadApp();
});

Given('I have a completed todo {string}', function (title) {
  this.localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: Date.now() + 1, title: title, completed: true }
  ]));
  this.loadApp();
});

Given('I have todos {string} and {string}', function (title1, title2) {
  this.localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: Date.now() + 1, title: title1, completed: false },
    { id: Date.now() + 2, title: title2, completed: false }
  ]));
  this.loadApp();
});

Given('I have a completed todo {string} and an active todo {string}', function (completed, active) {
  this.localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: Date.now() + 1, title: completed, completed: true },
    { id: Date.now() + 2, title: active, completed: false }
  ]));
  this.loadApp();
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('I type {string} into the new todo input and press Enter', function (text) {
  var input = qs(this.document, '.new-todo');
  assert.ok(input, 'New todo input should exist');
  setInputValue(input, text);
  triggerKeyboardEvent(input, 'keydown', 'Enter');
  // Some implementations listen for keydown with keyCode, so dispatch that too
  var evt = this.document.createEvent('KeyboardEvent');
  evt.initKeyboardEvent('keydown', true, true, null, 0, false, false, false, false, 'Enter');
  Object.defineProperty(evt, 'keyCode', { value: 13 });
  Object.defineProperty(evt, 'which', { value: 13 });
  input.dispatchEvent(evt);
});

When('I click the checkbox for {string}', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  var checkbox = li.querySelector('.toggle');
  assert.ok(checkbox, 'Checkbox should exist for "' + title + '"');
  checkbox.click();
});

When('I click the destroy button for {string}', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  var btn = li.querySelector('.destroy');
  assert.ok(btn, 'Destroy button should exist for "' + title + '"');
  btn.click();
});

When('I click the {string} toggle', function (label) {
  if (label === 'Mark all as complete') {
    var toggle = qs(this.document, '.toggle-all');
    assert.ok(toggle, 'Toggle all checkbox should exist');
    toggle.click();
  }
});

When('I complete all todos individually', function () {
  var items = qsa(this.document, '.todo-list li');
  items.forEach(function (li) {
    var checkbox = li.querySelector('.toggle');
    if (checkbox && !checkbox.checked) {
      checkbox.click();
    }
  });
});

When('I click {string}', function (label) {
  if (label === 'Clear completed') {
    var btn = qs(this.document, '.clear-completed');
    assert.ok(btn, 'Clear completed button should exist');
    btn.click();
  }
});

When('I double-click {string} and change it to {string}', function (oldText, newText) {
  var li = todoLabel(this.document, oldText);
  assert.ok(li, 'Todo "' + oldText + '" should exist');
  var label = li.querySelector('label');
  assert.ok(label, 'Label should exist for "' + oldText + '"');
  // Double-click the label to enter edit mode
  triggerEvent(label, 'dblclick');
  // Find the edit input
  var editInput = li.querySelector('.edit');
  assert.ok(editInput, 'Edit input should exist after double-click');
  // Set the new value
  setInputValue(editInput, newText);
});

When('I press Enter', function () {
  var editInput = qs(this.document, '.todo-list li.editing .edit');
  if (editInput) {
    var evt = this.document.createEvent('KeyboardEvent');
    evt.initKeyboardEvent('keydown', true, true, null, 0, false, false, false, false, 'Enter');
    Object.defineProperty(evt, 'keyCode', { value: 13 });
    Object.defineProperty(evt, 'which', { value: 13 });
    editInput.dispatchEvent(evt);
  }
});

When('I press Escape', function () {
  var editInput = qs(this.document, '.todo-list li.editing .edit');
  if (editInput) {
    var evt = this.document.createEvent('KeyboardEvent');
    evt.initKeyboardEvent('keydown', true, true, null, 0, false, false, false, false, 'Escape');
    Object.defineProperty(evt, 'keyCode', { value: 27 });
    Object.defineProperty(evt, 'which', { value: 27 });
    editInput.dispatchEvent(evt);
  }
});

When('I double-click {string} and clear the text', function (oldText) {
  var li = todoLabel(this.document, oldText);
  assert.ok(li, 'Todo "' + oldText + '" should exist');
  var label = li.querySelector('label');
  assert.ok(label, 'Label should exist for "' + oldText + '"');
  triggerEvent(label, 'dblclick');
  var editInput = li.querySelector('.edit');
  assert.ok(editInput, 'Edit input should exist after double-click');
  setInputValue(editInput, '');
});

When('the edit input loses focus', function () {
  var editInput = qs(this.document, '.todo-list li.editing .edit');
  if (editInput) {
    triggerEvent(editInput, 'blur');
  }
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I reload the app', function () {
  this.loadApp();
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('I should see {string} in the todo list', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(li, 'Expected todo "' + title + '" to be in the list');
});

Then('I should not see {string} in the todo list', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(!li, 'Expected todo "' + title + '" to NOT be in the list');
});

Then('the new todo input should be cleared', function () {
  var input = qs(this.document, '.new-todo');
  assert.ok(input, 'New todo input should exist');
  assert.strictEqual(input.value, '', 'New todo input should be empty after creating a todo');
});

Then('I should not see any new todos in the list', function () {
  var items = qsa(this.document, '.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected no todo items in the list');
});

Then('the main section should be hidden', function () {
  var main = qs(this.document, '.main');
  assert.ok(main, 'Main section should exist');
  var style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'Main section should be hidden');
});

Then('the footer section should be hidden', function () {
  var footer = qs(this.document, '.footer');
  assert.ok(footer, 'Footer section should exist');
  var style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Footer section should be hidden');
});

Then('the main section should be visible', function () {
  var main = qs(this.document, '.main');
  assert.ok(main, 'Main section should exist');
  var style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'Main section should be visible');
});

Then('the footer section should be visible', function () {
  var footer = qs(this.document, '.footer');
  assert.ok(footer, 'Footer section should exist');
  var style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'Footer section should be visible');
});

Then('{string} should be marked as completed', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(li.classList.contains('completed'), 'Todo "' + title + '" should have completed class');
});

Then('{string} should not be marked as completed', function (title) {
  var li = todoLabel(this.document, title);
  assert.ok(li, 'Todo "' + title + '" should exist');
  assert.ok(!li.classList.contains('completed'), 'Todo "' + title + '" should NOT have completed class');
});

Then('all todos should be completed', function () {
  var items = qsa(this.document, '.todo-list li');
  assert.ok(items.length > 0, 'There should be at least one todo');
  items.forEach(function (li) {
    assert.ok(li.classList.contains('completed'), 'All todos should have completed class');
  });
});

Then('the {string} toggle should be checked', function (label) {
  if (label === 'Mark all as complete') {
    var toggle = qs(this.document, '.toggle-all');
    assert.ok(toggle, 'Toggle all checkbox should exist');
    assert.ok(toggle.checked, 'Toggle all checkbox should be checked');
  }
});

Then('the {string} button should be hidden', function (label) {
  if (label === 'Clear completed') {
    var btn = qs(this.document, '.clear-completed');
    // Button may not exist or may be hidden
    if (btn) {
      var style = this.window.getComputedStyle(btn);
      assert.strictEqual(style.display, 'none', 'Clear completed button should be hidden');
    }
  }
});

Then('the {string} button should be visible', function (label) {
  if (label === 'Clear completed') {
    var btn = qs(this.document, '.clear-completed');
    assert.ok(btn, 'Clear completed button should exist');
    var style = this.window.getComputedStyle(btn);
    assert.notStrictEqual(style.display, 'none', 'Clear completed button should be visible');
  }
});

Then('the counter should show {string}', function (expected) {
  var countEl = qs(this.document, '.todo-count');
  assert.ok(countEl, 'Todo count element should exist');
  assert.strictEqual(countEl.textContent.trim(), expected, 'Counter should show "' + expected + '"');
});

Then('the {string} filter link should have the {string} class', function (filter, className) {
  var links = qsa(this.document, '.filters a');
  var found = false;
  links.forEach(function (a) {
    if (a.textContent.trim() === filter) {
      assert.ok(a.classList.contains(className), 'Filter link "' + filter + '" should have class "' + className + '"');
      found = true;
    }
  });
  assert.ok(found, 'Filter link "' + filter + '" should exist');
});

Then('the todo {string} should be saved in localStorage', function (title) {
  var data = JSON.parse(this.localStorage.getItem(STORAGE_KEY) || '[]');
  var found = data.some(function (t) { return t.title === title; });
  assert.ok(found, 'Todo "' + title + '" should be saved in localStorage');
});

/**
 * @planks("the app is loaded")
 * @planks("I have a todo {string}")
 * @planks("I have a completed todo {string}")
 * @planks("I have todos {string} and {string}")
 * @planks("I have a completed todo {string} and an active todo {string}")
 * @planks("there are no todos")
 * @planks("I reload the app")
 */

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  var todoModel = {
    getTodos: function () {
      try {
        return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
      } catch (e) {
        return [];
      }
    },
    setTodos: function (todos) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    },
    addTodo: function (title) {
      var todos = this.getTodos();
      var id = Date.now() + Math.random();
      todos.push({ id: id, title: title, completed: false });
      this.setTodos(todos);
      return todos;
    },
    deleteTodo: function (id) {
      var todos = this.getTodos();
      todos = todos.filter(function (t) { return t.id !== id; });
      this.setTodos(todos);
      return todos;
    },
    toggleTodo: function (id) {
      var todos = this.getTodos();
      todos.forEach(function (t) {
        if (t.id === id) { t.completed = !t.completed; }
      });
      this.setTodos(todos);
      return todos;
    },
    updateTodo: function (id, title) {
      var todos = this.getTodos();
      todos.forEach(function (t) {
        if (t.id === id) { t.title = title; }
      });
      this.setTodos(todos);
      return todos;
    },
    toggleAll: function (completed) {
      var todos = this.getTodos();
      todos.forEach(function (t) { t.completed = completed; });
      this.setTodos(todos);
      return todos;
    },
    clearCompleted: function () {
      var todos = this.getTodos();
      todos = todos.filter(function (t) { return !t.completed; });
      this.setTodos(todos);
      return todos;
    },
    getActiveCount: function () {
      return this.getTodos().filter(function (t) { return !t.completed; }).length;
    },
    getCompletedCount: function () {
      return this.getTodos().filter(function (t) { return t.completed; }).length;
    }
  };

  // -----------------------------------------------------------------------
  // View / Controller
  // -----------------------------------------------------------------------

  var app = {
    todos: [],
    filter: 'all',

    init: function () {
      this.todos = todoModel.getTodos();
      this.readFilter();
      this.bindEvents();
      this.render();
    },

    readFilter: function () {
      var hash = window.location.hash.replace('#/', '') || 'all';
      if (hash === '') { hash = 'all'; }
      if (hash !== 'all' && hash !== 'active' && hash !== 'completed') {
        hash = 'all';
      }
      this.filter = hash;
    },

    filteredTodos: function () {
      if (this.filter === 'active') {
        return this.todos.filter(function (t) { return !t.completed; });
      }
      if (this.filter === 'completed') {
        return this.todos.filter(function (t) { return t.completed; });
      }
      return this.todos;
    },

    bindEvents: function () {
      var self = this;

      // New todo
      var newTodo = document.querySelector('.new-todo');
      newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          var val = this.value.trim();
          if (val) {
            self.todos = todoModel.addTodo(val);
            this.value = '';
            self.render();
          }
        }
      });

      // Toggle all
      var toggleAll = document.querySelector('.toggle-all');
      toggleAll.addEventListener('change', function () {
        self.todos = todoModel.toggleAll(this.checked);
        self.render();
      });

      // Clear completed
      var clearBtn = document.querySelector('.clear-completed');
      clearBtn.addEventListener('click', function () {
        self.todos = todoModel.clearCompleted();
        self.render();
      });

      // Todo list events (delegated)
      var todoList = document.querySelector('.todo-list');
      todoList.addEventListener('click', function (e) {
        var li = e.target.closest('li');
        if (!li) { return; }
        var id = Number(li.dataset.id);

        // Toggle checkbox
        if (e.target.classList.contains('toggle')) {
          self.todos = todoModel.toggleTodo(id);
          self.render();
        }

        // Destroy button
        if (e.target.classList.contains('destroy')) {
          self.todos = todoModel.deleteTodo(id);
          self.render();
        }
      });

      // Double-click to edit (delegated)
      todoList.addEventListener('dblclick', function (e) {
        var label = e.target.closest('label');
        if (!label) { return; }
        var li = label.closest('li');
        if (!li) { return; }
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.value = li.querySelector('label').textContent.trim();
        editInput.focus();

        // Select all text
        editInput.setSelectionRange(editInput.value.length, editInput.value.length);
      });

      // Edit events (delegated)
      todoList.addEventListener('keydown', function (e) {
        var editInput = e.target.closest('.edit');
        if (!editInput) { return; }
        var li = editInput.closest('li');
        var id = Number(li.dataset.id);

        if (e.keyCode === ENTER_KEY) {
          self.commitEdit(li, id, editInput);
        } else if (e.keyCode === ESCAPE_KEY) {
          li.classList.remove('editing');
          editInput.value = li.querySelector('label').textContent.trim();
        }
      });

      // Blur on edit saves
      todoList.addEventListener('focusout', function (e) {
        var editInput = e.target.closest('.edit');
        if (!editInput) { return; }
        var li = editInput.closest('li');
        if (!li.classList.contains('editing')) { return; }
        var id = Number(li.dataset.id);
        self.commitEdit(li, id, editInput);
      });

      // Hash routing
      window.addEventListener('hashchange', function () {
        self.readFilter();
        self.updateFilterUI();
        self.render();
      });
    },

    commitEdit: function (li, id, editInput) {
      var val = editInput.value.trim();
      li.classList.remove('editing');
      if (val) {
        this.todos = todoModel.updateTodo(id, val);
      } else {
        this.todos = todoModel.deleteTodo(id);
      }
      this.render();
    },

    updateFilterUI: function () {
      var links = document.querySelectorAll('.filters a');
      links.forEach(function (a) {
        a.classList.remove('selected');
        var href = a.getAttribute('href').replace('#/', '') || 'all';
        if (href === '') { href = 'all'; }
        if (href === this.filter) {
          a.classList.add('selected');
        }
      }, this);
    },

    render: function () {
      var self = this;
      var filtered = this.filteredTodos();
      var todoList = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var countEl = document.querySelector('.todo-count');
      var clearBtn = document.querySelector('.clear-completed');
      var toggleAll = document.querySelector('.toggle-all');

      // Show/hide main and footer
      var hasTodos = this.todos.length > 0;
      main.style.display = hasTodos ? 'block' : 'none';
      footer.style.display = hasTodos ? 'block' : 'none';

      // Render list
      todoList.innerHTML = '';
      filtered.forEach(function (todo) {
        var li = document.createElement('li');
        li.dataset.id = todo.id;
        if (todo.completed) { li.classList.add('completed'); }

        li.innerHTML =
          '<div class="view">' +
            '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
            '<label>' + self.escapeHtml(todo.title) + '</label>' +
            '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';

        todoList.appendChild(li);
      });

      // Counter
      var activeCount = todoModel.getActiveCount();
      var itemWord = activeCount === 1 ? 'item' : 'items';
      countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

      // Clear completed visibility
      var completedCount = todoModel.getCompletedCount();
      clearBtn.style.display = completedCount > 0 ? 'block' : 'none';

      // Toggle all state
      toggleAll.checked = this.todos.length > 0 && activeCount === 0;
    },

    escapeHtml: function (str) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(str));
      return div.innerHTML;
    }
  };

  // -----------------------------------------------------------------------
  // Boot
  // -----------------------------------------------------------------------

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { app.init(); });
  } else {
    app.init();
  }
})();

